import AppKit

/// E31-03: filters a pasteboard item out of clipboard sync when its types carry any of the
/// nspasteboard.org conventions for content that must never leave the machine -- concealed
/// (password managers), transient (one-shot clips), or auto-generated (derived, not user intent).
///
/// Callers must check ``shouldSkip(types:)`` against ``PasteboardSource/types()`` *before* ever
/// calling ``PasteboardSource/string(forType:)`` for the same item: this keeps a concealed item's
/// content from being read into memory at all on a path that's going to skip it anyway, and keeps
/// invariant 7 ("no logging of secrets or clipboard content") trivially true here, since this type
/// only ever sees a type list, never a string.
public enum ConcealedTypeFilter {
    static let concealedType = NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType")
    static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

    private static let skippedTypes: Set<NSPasteboard.PasteboardType> = [
        concealedType, transientType, autoGeneratedType
    ]

    /// Whether an item advertising `types` must be skipped entirely: no send, no logging.
    public static func shouldSkip(types: [NSPasteboard.PasteboardType]) -> Bool {
        !skippedTypes.isDisjoint(with: types)
    }
}
